import{_ as t,o as i,c as a,a2 as h}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse(`{"title":"Celestial condition vs. Planet's Nature","description":"","frontmatter":{"title":"Celestial condition vs. Planet's Nature","date":"2026-09-06T00:00:00.000Z"},"headers":[],"relativePath":"astro/note_2.md","filePath":"astro/note_2.md"}`),o={name:"astro/note_2.md"};function e(r,n,s,c,l,g){return i(),a("div",null,[...n[0]||(n[0]=[h('<h2 id="planet-s-own-nature-ban-chat-khong-đoi-cua-hanh-tinh" tabindex="-1">&quot;Planet&#39;s own nature&quot; = bản chất KHÔNG ĐỔI của hành tinh <a class="header-anchor" href="#planet-s-own-nature-ban-chat-khong-đoi-cua-hanh-tinh" aria-label="Permalink to &quot;&quot;Planet&#39;s own nature&quot; = bản chất KHÔNG ĐỔI của hành tinh&quot;">​</a></h2><p>Đây là <strong>bản chất cố định, vĩnh viễn</strong> của mỗi hành tinh với tư cách là một &quot;vị thần&quot; (planetary god) riêng biệt — không bao giờ thay đổi, bất kể ngày nào, vị trí nào:</p><ul><li>Saturn <strong>luôn luôn</strong> là greater malefic, lạnh, khô, liên quan đến giới hạn/thời gian/tuổi già</li><li>Venus <strong>luôn luôn</strong> là lesser benefic, ấm, ẩm, liên quan đến tình yêu/vẻ đẹp/hòa hợp</li><li>Mars <strong>luôn luôn</strong> là lesser malefic, nóng, khô, liên quan đến xung đột/hành động</li></ul><p>→ Đây giống như &quot;loài&quot; hay &quot;chủng tộc&quot; của hành tinh — là cái <strong>họ LÀ</strong> (identity), không phải cái họ <strong>ĐANG Ở ĐÂU</strong> (position). Dù Mars nằm ở sign nào, phase nào, nó vẫn mãi mãi là Mars với bản chất hỏa-khô-malefic đó.</p><h2 id="celestial-condition-tinh-trang-thay-đoi-theo-tung-ngay" tabindex="-1">&quot;Celestial condition&quot; = tình trạng THAY ĐỔI theo từng ngày <a class="header-anchor" href="#celestial-condition-tinh-trang-thay-đoi-theo-tung-ngay" aria-label="Permalink to &quot;&quot;Celestial condition&quot; = tình trạng THAY ĐỔI theo từng ngày&quot;">​</a></h2><p>Đây là vị trí <strong>cụ thể, biến động</strong> của hành tinh đó vào MỘT ngày cụ thể — tức là 3 yếu tố bạn đã học (sign/dignity, solar phase, aspect):</p><ul><li>Hôm nay Mars ở Capricorn (exaltation) → điều kiện tốt</li><li>Ngày mai/tháng sau Mars ở Cancer (fall) → điều kiện xấu</li><li>Mars retrograde tháng này → điều kiện yếu về mặt biểu hiện</li></ul><p>→ Cái này <strong>thay đổi liên tục</strong> theo chuyển động thiên thể — chính là lý do celestial condition khác nhau tùy ngày sinh (dù vẫn giống nhau cho mọi người sinh cùng ngày).</p><h2 id="an-du-đe-de-hinh-dung" tabindex="-1">Ẩn dụ để dễ hình dung <a class="header-anchor" href="#an-du-đe-de-hinh-dung" aria-label="Permalink to &quot;Ẩn dụ để dễ hình dung&quot;">​</a></h2><p>Giống như phân biệt giữa <strong>con người bạn LÀ</strong> và <strong>hoàn cảnh bạn ĐANG ở</strong>:</p><table tabindex="0"><thead><tr><th></th><th>Planet&#39;s own nature</th><th>Celestial condition</th></tr></thead><tbody><tr><td>Ẩn dụ</td><td>Tính cách bẩm sinh của một người (hướng nội/hướng ngoại, nóng tính/điềm đạm)</td><td>Hoàn cảnh sống hiện tại của người đó (đang có việc tốt hay thất nghiệp, đang khỏe hay ốm)</td></tr><tr><td>Cố định?</td><td>Có — không đổi suốt &quot;cuộc đời&quot; của khái niệm hành tinh đó</td><td>Không — thay đổi từng ngày, từng giờ</td></tr><tr><td>Ví dụ</td><td>Mars = nóng nảy, hiếu chiến (bản chất)</td><td>Mars hôm nay đang ở exaltation, đi thuận (điều kiện tốt hôm nay)</td></tr></tbody></table><h2 id="vay-tai-sao-ca-hai-van-thuoc-divine-celestial" tabindex="-1">Vậy tại sao cả hai vẫn &quot;thuộc divine/celestial&quot;? <a class="header-anchor" href="#vay-tai-sao-ca-hai-van-thuoc-divine-celestial" aria-label="Permalink to &quot;Vậy tại sao cả hai vẫn &quot;thuộc divine/celestial&quot;?&quot;">​</a></h2><p>Đúng là cả hai đều <strong>không phải terrestrial</strong> — cả bản chất lẫn condition của hành tinh đều thuộc <strong>cõi trời</strong> (celestial realm), khác với houses (terrestrial). Nhưng trong triết học Hy Lạp cổ (đặc biệt là phân biệt kiểu Aristotle giữa <strong>substance/essence</strong> và <strong>accident</strong>):</p><ul><li><strong>Bản chất (nature/essence)</strong> = cái gì đó là <strong>bất biến, nội tại</strong>, thuộc về chính &quot;hình dạng&quot; (form) của sự vật — dù nó ở cõi trời hay đâu</li><li><strong>Điều kiện (condition)</strong> = cái gì đó <strong>biến đổi theo thời gian và hoàn cảnh</strong>, dù vẫn xảy ra trong cùng cõi trời đó</li></ul><p>→ Nên chính xác hơn phải nói: <strong>cả hai đều là &quot;celestial&quot;</strong>, nhưng bản chất là phần <strong>cố định/essential</strong> của hành tinh, còn celestial condition là phần <strong>biến đổi/circumstantial</strong> của chính hành tinh đó trong cõi trời — <strong>không phải</strong> sự phân biệt celestial vs terrestrial (đó là phân biệt khác, giữa condition và house placement).</p>',15)])])}const p=t(o,[["render",e]]);export{d as __pageData,p as default};
